Translate("ptBR", "thousand-needles", {
	title = "Mil Agulhas",
	aliases = { "as Agulhas", "as Mil Agulhas" },
	sections = {
		{
			title = "Resumo",
			text = [=[Mil Agulhas é um grande cânion de pedra vermelha ao sul dos {link:the-barrens}Sertões{/link}. Seu leito é seco e poeirento, e dele se erguem centenas de agulhas estreitas de rocha, tão altas e finas que os viajantes deram o nome delas a toda a terra. Os {link:tauren}tauren{/link} chegam até ele pelo {link:the-great-lift}Grande Elevador{/link} em sua borda norte e, dos platôs da {link:freewind-post}Aldeia Vento Livre{/link}, vigiam o cânion. A leste, a pedra dá lugar à {link:the-shimmering-flats}Chapada Cintilante{/link}, uma planície ofuscante de sal onde goblins e gnomos correm com máquinas de sua própria fabricação. Serpentes aladas se enroscam entre as agulhas, mantícoras fazem ninho nas alturas do oeste, e harpias gritam nos cânions do sul. É uma terra bela, e perigosa.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra como as agulhas vieram a se erguer como estão, nem quando {link:the-shimmering-flats}a Chapada{/link} Cintilante se tornou um deserto de sal. Os {link:tauren}tauren{/link} percorrem estes cânions há gerações, e os {link:centaurs}centauros{/link} os caçavam aqui como os caçavam por todas as planícies de {link:kalimdor}Kalimdor{/link}. Estudiosos que vêm à Chapada notam que a fronteira entre as matas verdes de {link:feralas}Feralas{/link} e a pedra seca das Agulhas é estranhamente nítida, como se alguma magia antiga a tivesse traçado. Nenhum deles sabe dizer que magia foi essa.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[Os {link:tauren}tauren{/link} da {link:freewind-post}Aldeia Vento Livre{/link} dominam o coração do cânion, mas pouco além disso. Os centauros Galath atacam suas caravanas a partir do {link:splithoof-crag}Rochedo do Casco Fendido{/link} e da {link:camp-e-thok}Aldeia E'thok{/link}, e juraram matar qualquer tauren que ouse caçar no oeste. No {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link}, guerreiros do {link:grimtotem-clan}clã Temível Totem{/link} guardam o cemitério de seus mortos e recebem estranhos que vêm e vão em segredo. A Aldeia Vento Livre os vigia de perto e confia menos neles a cada estação.

No leste, {link:the-shimmering-flats}a Chapada{/link} Cintilante se tornou o palco de uma longa disputa. No {link:mirage-raceway}Circuito da Ilusão{/link}, uma equipe goblin e uma equipe gnômica correm com seus carros-foguete pelo sal, e metade dos malandros e sonhadores do mundo vem assistir e apostar. Ao sul da pista, anões da {link:explorers-league}Liga dos Exploradores{/link} escavaram a terra no {link:the-rustmaul-dig-site}Sítio de Escavação Velhomalho{/link}, e algo escavou de volta: um enxame de grandes insetos que a {link:horde}Horda{/link} agora chama de silitídeos. Na borda norte, perto do elevador, os javaligres mantêm a toca espinhosa de {link:razorfen-downs}Urzal dos Mortos{/link}, e cultistas de manto foram vistos nas trilhas próximas.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os {link:tauren}tauren{/link}.{/b} Bravos, caçadores e xamãs mantêm a {link:freewind-post}Aldeia Vento Livre{/link} e o pequeno acampamento de caça do {link:whitereach-post}Posto Confinalvo{/link}.
• {b}Os Temível Totem.{/b} Um clã tauren à parte, que domina o {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link} e desconfia de todas as outras tribos.
• {b}Os centauros Galath.{/b} Saqueadores que dominam o {link:splithoof-crag}Rochedo do Casco Fendido{/link} e a {link:camp-e-thok}Aldeia E'thok{/link} e guerreiam contra os tauren.
• {b}Os goblins e gnomos do {link:mirage-raceway}Circuito da Ilusão{/link}.{/b} Mecânicos, pilotos, agenciadores de apostas e parasitas.
• {b}As harpias.{/b} As harpias Uivantes fazem ninho na Garganta Uivante e no {link:roguefeather-den}Covil Plumerrante{/link}.
• {b}Os silitídeos.{/b} Insetos que enxameiam da terra sob o {link:the-rustmaul-dig-site}Sítio de Escavação Velhomalho{/link}.
• {b}As feras.{/b} Serpentes aladas, mantícoras, pumas, hienas, basiliscos, escorpídeos e as grandes tartarugas do sal.]=],
		},
		{
			title = "História",
			text = [=[• {b}Os Anos de Andança.{/b} As tribos {link:tauren}tauren{/link} atravessaram estes cânions em suas longas andanças, caçadas pelos centauros. Muitos tauren da {link:freewind-post}Aldeia Vento Livre{/link} ainda se lembram daqueles dias.
• {b}A Conquista de Mulgore.{/b} Quando {link:cairne-bloodhoof}Cairne Bloodhoof{/link} levou seu povo a {link:mulgore}Mulgore{/link} com a ajuda da {link:horde}Horda{/link}, os tauren ficaram fortes o bastante para voltar às Agulhas. Nenhuma crônica registra quando ergueram a Aldeia Vento Livre ou o {link:the-great-lift}Grande Elevador{/link}.
• {b}A Chegada dos Corredores.{/b} Goblins e gnomos encontraram na {link:the-shimmering-flats}Chapada Cintilante{/link} o chão mais plano de {link:kalimdor}Kalimdor{/link}, e construíram sobre ele uma pista de corrida.
• {b}Os Dias Atuais.{/b} Os Galath ficam mais ousados, {link:grimtotem-clan}os Temível Totem{/link} guardam segredos, e os silitídeos subiram das profundezas da terra.]=],
		},
		{
			title = "O Saber das Agulhas",
			text = [=[• Os {link:tauren}tauren{/link} do {link:whitereach-post}Posto Confinalvo{/link} conhecem uma lenda de {link:arikara}Arikara{/link}, uma serpente da vingança que se ergue do fogo sagrado do {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link} contra quem cometeu atos hediondos. A maioria a julgava apenas uma lenda.
• Os Galath guardam uma relíquia dos dias em que os primeiros centauros nasceram, mantida numa caverna atrás de uma chama que nunca se apaga.
• Uma hiena que os tauren chamam de {link:steelsnap}Steelsnap{/link} reúne outras hienas em torno de si e espalha o medo entre as feras mais mansas do cânion.
• As equipes de box do {link:mirage-raceway}Circuito da Ilusão{/link} dizem que cada trecho da Chapada está coberto de destroços de carros-foguete, e que um catador cuidadoso pode viver disso.]=],
		},
	},
})

Translate("ptBR", "freewind-post", {
	title = "Aldeia Vento Livre",
	aliases = { "Vento Livre" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Aldeia Vento Livre é a fortaleza {link:tauren}tauren{/link} de {link:thousand-needles}Mil Agulhas{/link}, erguida sobre um grupo de platôs no meio do cânion. Pontes de corda e madeira ligam os topos dos platôs, e um elevador leva os viajantes desde o leito do cânion. O {link:cliffwatcher-longhorn}Vigia do Penhasco Longhorn{/link} comanda seus bravos. A Taverneira Abeqwa cuida da cabana, Montarr guarda o saber das tribos, e os cavaleiros de mantícora de Nyse levam notícias ao {link:thunder-bluff}Penhasco do Trovão{/link} e à {link:the-crossroads}Encruzilhada{/link}. Num poste junto à cabana pende um aviso que todo bravo já leu: uma recompensa pelo pária Temível Totem {link:arnak-grimtotem}Arnak{/link}. De suas alturas os tauren conseguem ver os acampamentos Galath ao norte e o pináculo dos Temível Totem a noroeste.]=],
		},
	},
})

Translate("ptBR", "the-great-lift", {
	title = "O Grande Elevador",
	aliases = { "Grande Elevador" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Grande Elevador liga a borda sul dos {link:the-barrens}Sertões{/link} ao leito de {link:thousand-needles}Mil Agulhas{/link}, muito abaixo. Os {link:tauren}tauren{/link} o construíram, e suas plataformas sobem e descem em longas cordas ao lado do penhasco. É o único caminho fácil para o cânion vindo do norte, e por isso é guardado. Grish Longrunner monta guarda nele há tanto tempo que o chama de um monte de madeira, e espera há muitas estações ser substituído para poder visitar sua família. O Bravo Moonhorn vigia a trilha abaixo, onde os ataques dos centauros têm ficado mais frequentes.]=],
		},
	},
})

Translate("ptBR", "whitereach-post", {
	title = "Posto Confinalvo",
	aliases = { "Confinalvo" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Posto Confinalvo é um pequeno acampamento {link:tauren}tauren{/link} no noroeste do cânion, a sudoeste do {link:the-great-lift}Grande Elevador{/link} e ao longo da estrada para {link:freewind-post}Vento Livre{/link}. {link:kanati-greycloud}Kanati Greycloud{/link} o montou como acampamento de caça, ousado o bastante para caçar nos cânions do oeste que os Galath reivindicam. {link:motega-firemane}Motega Firemane{/link} veio para cá com o jovem {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link} para estudar as criaturas das Agulhas. Um engenhoqueiro goblin, {link:wizlo-bearingshiner}Wizlo Bearingshiner{/link}, abrigou-se entre eles depois que os centauros destruíram sua caravana. Os Galath pretendem varrer o acampamento, e suas poucas tendas estão sempre sob vigia.]=],
		},
	},
})

Translate("ptBR", "darkcloud-pinnacle", {
	title = "Pináculo da Nuvem Negra",
	sections = {
		{
			title = "Resumo",
			text = [=[O Pináculo da Nuvem Negra é um grupo de agulhas no noroeste do cânion, dominado pelo {link:grimtotem-clan}clã Temível Totem{/link}. Trilhas e pontes sobem entre seus picos, e numa agulha isolada os Temível Totem enterram seus mortos junto a um fogo sagrado da vida que há muito jaz adormecido. O clã guarda o lugar com ferocidade. Agentes de origem desconhecida o visitaram em segredo, deixando cartas seladas nos baús dos Temível Totem. {link:arnak-grimtotem}Arnak{/link}, o pária, espreita nos penhascos próximos, e foi para cá que ele trouxe a {link:tauren}tauren{/link} que havia raptado.]=],
		},
	},
})

Translate("ptBR", "splithoof-crag", {
	title = "Rochedo do Casco Fendido",
	aliases = { "Castelo do Casco Fendido" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Rochedo do Casco Fendido é a fortaleza dos {link:centaurs}centauros{/link} Galath, uma aldeia de tendas de couro contra a parede norte do cânion, a leste do {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link} e ao norte da {link:freewind-post}Aldeia Vento Livre{/link}. Seus saqueadores cavalgam contra as caravanas {link:tauren}tauren{/link}, e seus batedores chegam até a própria borda dos platôs de Vento Livre. No fundo do rochedo fica o Castelo do Casco Fendido, uma caverna guardada. Ali, atrás de um braseiro antigo cuja chama nunca morre, os Galath guardam o Casco Fendido, uma relíquia do tempo em que sua raça nasceu.]=],
		},
	},
})

Translate("ptBR", "camp-e-thok", {
	title = "Aldeia E'thok",
	sections = {
		{
			title = "Resumo",
			text = [=[A Aldeia E'thok é um acampamento de guerra Galath no extremo noroeste de {link:thousand-needles}Mil Agulhas{/link}, não muito abaixo dos {link:the-barrens}Sertões{/link}. Perto dela jazem as carroças quebradas de uma caravana goblin que os centauros atacaram e saquearam. Levaram tudo, menos uma pantera enjaulada, uma fera tão feroz que até os centauros a temem. No pescoço da pantera ainda pende o precioso aparelho de {link:wizlo-bearingshiner}Wizlo Bearingshiner{/link}, o único sobrevivente da caravana. A hiena {link:steelsnap}Steelsnap{/link} e sua matilha rondam as encostas próximas.]=],
		},
	},
})

Translate("ptBR", "highperch", {
	title = "Alcândora",
	sections = {
		{
			title = "Resumo",
			text = [=[Alcândora é uma alta plataforma de rocha na borda oeste do cânion, alcançada por uma rampa ao longo das paredes do penhasco. É o local de ninhos das mantícoras de Alcândora, e elas defendem seus ovos com devoção selvagem. Os {link:tauren}tauren{/link} de {link:freewind-post}Vento Livre{/link} recolhem ovos aqui para criar novas montarias para os cavaleiros de mantícora da {link:horde}Horda{/link}. Outros vêm pelo veneno das mantícoras, que alcança um preço alto em certos círculos. Uma grande mantícora que os caçadores chamam de Heartrazor domina os céus acima dos ninhos.]=],
		},
	},
})

Translate("ptBR", "roguefeather-den", {
	title = "Covil Plumerrante",
	sections = {
		{
			title = "Resumo",
			text = [=[O Covil Plumerrante é uma caverna no sul do cânion, a oeste da {link:freewind-post}Aldeia Vento Livre{/link}, no fim da Garganta Uivante. As {link:harpies}harpias{/link} Uivantes fazem ninho ali, e nas profundezas do covil amontoam a comida que roubaram do cânion. Sua matriarca, {link:grenka-bloodscreech}Grenka Bloodscreech{/link}, não se mostra a estranhos, mas quem estraga as provisões das harpias logo aprende com que rapidez ela vem. Por isso os {link:tauren}tauren{/link} que põem os jovens à prova os mandam aqui para provar sua resistência.]=],
		},
	},
})

Translate("ptBR", "windbreak-canyon", {
	title = "Garganta do Quebravento",
	sections = {
		{
			title = "Resumo",
			text = [=[A Garganta do Quebravento corre ao longo do lado norte da estrada entre a {link:freewind-post}Aldeia Vento Livre{/link} e {link:the-shimmering-flats}a Chapada{/link} Cintilante. Serpentes aladas fazem ninho em suas tocas ao longo da base dos penhascos, e se enroscam acima das agulhas ao entardecer. Numa dessas tocas, as serpentes foram encontradas guardando um ovo que não era delas. Numa altura solitária perto da garganta vive {link:dorn-plainstalker}Dorn Plainstalker{/link}, que põe à prova os jovens de todas as tribos, e perto dele mora a xamã {link:prate-cloudseer}Prate Cloudseer{/link}, que fala pelos espíritos do ar.]=],
		},
	},
})

Translate("ptBR", "the-shimmering-flats", {
	title = "Chapada Cintilante",
	aliases = { "a Chapada" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Chapada Cintilante ocupa o sudeste de {link:thousand-needles}Mil Agulhas{/link}: uma planície de sal branco tão plana e tão brilhante que o ar sobre ela tremula no calor. Escorpídeos incrustados de sal, basiliscos, abutres e grandes tartarugas cintilantes vivem nela, e crescem mais do que qualquer um consegue explicar. Goblins e gnomos fizeram da Chapada seu campo de corrida, e o trovão de seus motores ecoa nas paredes do cânion. Em sua borda sul, os anões escavaram o {link:the-rustmaul-dig-site}Sítio de Escavação Velhomalho{/link}. Em sua fronteira norte, um destacamento de guerra maltratado da {link:horde}Horda{/link} monta guarda.]=],
		},
	},
})

Translate("ptBR", "mirage-raceway", {
	title = "Circuito da Ilusão",
	aliases = { "o Circuito da Ilusão", "o Circuito" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Circuito da Ilusão é uma pista traçada na {link:the-shimmering-flats}Chapada Cintilante{/link}, com os boxes de duas equipes rivais em cada ponta de uma arquibancada. Os goblins constroem seus carros com dois motores e mais fogo do que juízo. Os gnomos, liderados pelos irmãos Brassbolts, constroem com cuidado e ainda assim batem. O {link:race-master-kronkrider}Mestre de Corrida Kronkrider{/link} governa a pista, locutores gritam as cotações, e vendedores oferecem bebidas e sorvete ao público. Por trás do barulho há dinheiro, e onde há dinheiro há tramas: planos roubados, equipes subornadas e pilotos com segredos a esconder.]=],
		},
	},
})

Translate("ptBR", "the-rustmaul-dig-site", {
	title = "Sítio de Escavação Velhomalho",
	aliases = { "Escavação Velhomalho" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Sítio de Escavação Velhomalho fica na borda sul da {link:the-shimmering-flats}Chapada Cintilante{/link}, onde uma equipe de escavação da {link:explorers-league}Liga dos Exploradores{/link} rasgou a terra. A {link:horde}Horda{/link} enviou um destacamento de guerra para expulsar os anões. O ataque deu certo, mas no meio dele um enxame de grandes insetos irrompeu de uma caverna dentro da escavação, e mais da metade dos orcs nunca voltou para casa. Os anões se foram. Os insetos ficaram, e seu número cresce: buscadores, zangões e invasores com carapaças mais fortes que qualquer armadura que os ferreiros da Horda conheçam.]=],
		},
	},
})

Translate("ptBR", "cliffwatcher-longhorn", {
	title = "Vigia do Penhasco Longhorn",
	subtitle = "Comandante da Aldeia Vento Livre",
	found = "Aldeia Vento Livre",
	hint = [=[Fale com o vigia do penhasco que comanda os bravos da Aldeia Vento Livre.]=],
	allegiance = "Horda · Aldeia Vento Livre",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vigia do Penhasco Longhorn comanda os bravos da {link:freewind-post}Aldeia Vento Livre{/link}. Dos altos platôs ele vigia toda {link:thousand-needles}Mil Agulhas{/link}, e nada ali lhe agrada. Os Galath atacam suas caravanas, {link:grimtotem-clan}os Temível Totem{/link} guardam seus próprios segredos no {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link}, e um assassino daquele clã anda livre pelos penhascos. É um líder duro e irado, lento em perdoar uma ofensa a seu povo.]=],
		},
		{
			title = "Importância",
			text = [=[Longhorn é o primeiro a ver a forma do problema que se forma nas Agulhas. Os centauros são apenas a parte mais ruidosa dele. Sua descoberta de que {link:grimtotem-clan}os Temível Totem{/link} negociam com estranhos de além de {link:kalimdor}Kalimdor{/link} é um aviso que chega muito além de um único cânion.]=],
		},
		{
			title = "Feitos",
			text = [=[• Jurou vingança contra os Galath quando massacraram uma de suas caravanas de suprimentos.
• Pôs a recompensa pela cabeça de {link:arnak-grimtotem}Arnak Grimtotem{/link} por assassinato e rapto.
• Enviou espiões ao {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link} para descobrir o que {link:grimtotem-clan}os Temível Totem{/link} escondiam.
• Mantém seu irmão Nataka, longe em {link:desolace}Desolação{/link}, informado dos movimentos dos centauros.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu sobre a vida de Longhorn antes da {link:freewind-post}Aldeia Vento Livre{/link}. Sabe-se apenas que ele tem um irmão, Nataka, que serve no {link:ghost-walker-post}Entreposto do Espírito que Anda{/link}, em {link:desolace}Desolação{/link}, e que um ano se passou entre duas de suas cartas para ele.]=],
		},
	},
	chapters = {
		{
			title = "A Ira de Vento Livre",
			hint = [=[Leve a mensagem urgente do Grande Elevador à Aldeia Vento Livre.]=],
			text = [=[Um bravo no {link:the-great-lift}Grande Elevador{/link} mandou avisar que os centauros haviam retomado seus ataques. A notícia chegou tarde demais para uma das caravanas de Longhorn: os Galath já haviam caído sobre ela e matado todos os {link:tauren}tauren{/link} que a acompanhavam. Longhorn chamou aquilo de ultraje e jurou que não ficaria impune. Enviou todo guerreiro disposto contra o acampamento Galath ao norte da aldeia.]=],
		},
		{
			title = "As Cartas Secretas",
			hint = [=[Descubra o que os Temível Totem escondem no Pináculo da Nuvem Negra.]=],
			text = [=[Ao longo de várias semanas, três estranhos de origem desconhecida foram vistos visitando {link:grimtotem-clan}os Temível Totem{/link}. Longhorn soube que cada um deixara uma mensagem num baú diferente no {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link}, e mandou tomá-las. As cartas eram endereçadas a um certo Agasham e assinadas por três que se chamavam Arautos. Falavam de uma aliança que as outras tribos {link:tauren}tauren{/link} jamais deveriam descobrir, de obediência total e de agentes de {link:lordaeron}Lordaeron{/link} que logo se encontrariam com os delegados de Agasham. Longhorn as leu e chamou a notícia de terrível. Começou a se preparar para o que quer que viesse.]=],
		},
	},
	mentions = {
		{
			text = [=[Mensagem para a {link:freewind-post}Aldeia Vento Livre{/link}, trazida pelo mensageiro do Bravo Moonhorn]=],
		},
		{ text = "Pacificar os {link:centaurs}Centauros{/link}" },
		{ text = "Espionando {link:grimtotem-clan}os Temível Totem{/link}" },
		{ text = "Procura-se: {link:arnak-grimtotem}Arnak Grimtotem{/link}" },
		{ text = "Árvore Genealógica, um relatório para seu irmão" },
	},
	bonds = {
		{ id = "arnak-grimtotem", name = "Arnak Grimtotem", note = "o pária que ele quer levar à justiça" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "serve na Aldeia Vento Livre" },
		{ id = "thalia-amberhide", name = "Thalia Amberhide", note = "serve na Aldeia Vento Livre" },
		{ id = "nataka-longhorn", name = "Nataka Longhorn", note = "seu irmão em Desolação" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "Velha Anciã do clã que ele vigia" },
	},
})

Translate("ptBR", "hagar-lightninghoof", {
	title = "Hagar Lightninghoof",
	subtitle = "Estudioso da Aldeia Vento Livre",
	found = "Aldeia Vento Livre",
	hint = [=[Fale com o tauren da Aldeia Vento Livre que tem curiosidade sobre um ovo estranho.]=],
	allegiance = "Horda · Aldeia Vento Livre",
	aliases = { "Hagar" },
	sections = {
		{
