Translate("ptBR", "motega-firemane", {
	title = "Motega Firemane",
	subtitle = "Guardião do Posto Confinalvo",
	found = "Posto Confinalvo",
	hint = [=[Fale com o tauren que estuda as criaturas das Agulhas no Posto Confinalvo.]=],
	allegiance = "Horda · Posto Confinalvo",
	aliases = { "Motega" },
	sections = {
		{
			title = "Resumo",
			text = [=[Motega Firemane veio a {link:thousand-needles}Mil Agulhas{/link} para estudar as criaturas que vivem ali, e trouxe consigo o jovem {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}. Mantém suas tendas no {link:whitereach-post}Posto Confinalvo{/link}, no noroeste do cânion. Motega conhece as velhas histórias dos {link:tauren}tauren{/link} melhor que a maioria, e quando uma serpente de lenda voltou às Agulhas, foi a ele que os tauren recorreram.]=],
		},
		{
			title = "Importância",
			text = [=[Motega é a ponte entre {link:thousand-needles}as Agulhas{/link} e a Velha Anciã. Foi ele quem mandou avisar {link:magatha-grimtotem}Magatha Grimtotem{/link} sobre a serpente {link:arikara}Arikara{/link}, e ele quem recebeu o pó que a chamaria do fogo sagrado. Foi também o primeiro a achar estranho o aviso dela.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estuda as criaturas de {link:thousand-needles}Mil Agulhas{/link} a partir do {link:whitereach-post}Posto Confinalvo{/link}.
• Cuida de {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}, cujo pai relutou em deixar o menino vir.
• Conhece a lenda de {link:arikara}Arikara{/link}, a serpente nascida para vingar atos hediondos.
• Pediu a ajuda de {link:magatha-grimtotem}Magatha{/link} para acender o fogo sagrado adormecido do {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link}.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu sobre a vida de Motega antes do {link:whitereach-post}Posto Confinalvo{/link}. Quem é o pai de {link:pao-ka-swiftmountain}Pao'ka{/link}, e por que confiou o menino a Motega, não está registrado.]=],
		},
	},
	chapters = {
		{
			title = "O Menino Perdido",
			hint = "Traga Pao'ka para casa de Alcândora.",
			text = [=[{link:pao-ka-swiftmountain}Pao'ka{/link} foi sozinho a {link:highperch}Alcândora{/link} estudar as mantícoras e não voltou. Quando o menino enfim foi trazido para casa, Motega ficou furioso. Disse que, se soubesse, o teria acorrentado a um totem. Por baixo da raiva, estava grato, e recompensou quem ajudara.]=],
		},
		{
			title = "A Lenda de Arikara",
			hint = "Responda ao aviso de Hagar Lightninghoof.",
			text = [=[Motega ouvira falar de {link:arikara}Arikara{/link} a vida toda e nunca acreditara que a veria. Agora a lenda era verdadeira. Para caçar a serpente, era preciso acender o fogo sagrado da vida no {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link}, e só um xamã poderoso podia encantar a rara agave Incendia que o acenderia. Motega enviou a agave colhida a {link:magatha-grimtotem}Magatha Grimtotem{/link}, no {link:thunder-bluff}Penhasco do Trovão{/link}.]=],
		},
		{
			title = "Uma Resposta Inquietante",
			hint = "Mate Arikara e volte ao Posto Confinalvo.",
			text = [=[A Velha Anciã avisara que {link:arikara}Arikara{/link} talvez estivesse perseguindo {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, enfurecida porque muito do antigo saber dos {link:tauren}tauren{/link} havia mudado. Quando a serpente foi morta, Motega balançou a cabeça. Não fazia sentido para ele que Arikara caçasse o Grande Chefe. Ainda assim, não quis dizer que {link:magatha-grimtotem}Magatha{/link} estivesse errada. Ela era, disse ele, a mais poderosa deles.]=],
		},
	},
	mentions = {
		{ text = "De Volta ao Lar" },
		{ text = "Serpente Selvagem" },
		{ text = "Fogo Sagrado" },
		{ text = "{link:arikara}Arikara{/link}" },
	},
	bonds = {
		{ id = "pao-ka-swiftmountain", name = "Pao'ka Swiftmountain", note = "o menino sob seus cuidados" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "trouxe-lhe a notícia" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "encantou o pó" },
		{ id = "arikara", name = "Arikara", note = "a serpente da lenda" },
		{ id = "kanati-greycloud", name = "Kanati Greycloud", note = "divide o Posto Confinalvo" },
	},
})

