Translate("ptBR", "dorn-plainstalker", {
	title = "Dorn Plainstalker",
	subtitle = "Examinador dos Jovens",
	found = "Uma altura solitária a nordeste da Aldeia Vento Livre",
	hint = [=[Procure o tauren que põe os jovens à prova numa altura solitária acima das Agulhas.]=],
	allegiance = "Horda",
	aliases = { "Dorn" },
	sections = {
		{
			title = "Resumo",
			text = [=[Dorn Plainstalker mora sozinho numa altura acima das Agulhas, longe do movimento da {link:freewind-post}Aldeia Vento Livre{/link}. Considera seu dever preparar os jovens de todas as tribos para os perigos que enfrentarão depois de deixar a segurança do lar. Ele os põe à prova em três coisas: o espírito, o corpo e a mente. Quem passa volta mais forte. Quem falha, diz ele, aprende o quão vasto o mundo realmente é.]=],
		},
		{
			title = "Importância",
			text = [=[Dorn é um mestre dos velhos tempos. Não lhe importa de que tribo vem um guerreiro, só se ele está pronto. Suas provas unem vários dos sábios da {link:horde}Horda{/link} por {link:kalimdor}Kalimdor{/link} e além.]=],
		},
		{
			title = "Feitos",
			text = [=[• Põe à prova a fé, a resistência, a força e o saber dos jovens.
• Envia-os contra a matriarca das harpias do {link:roguefeather-den}Covil Plumerrante{/link} e contra o elemental {link:rok-alim-the-pounder}Rok'Alim{/link}.
• Envia-os ao xamã {link:braug-dimspirit}Braug Dimspirit{/link}, na {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link}, para a prova do saber.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu sobre a vida de Dorn ou sobre há quanto tempo ele guarda sua altura. Sua tribo não é nomeada.]=],
		},
	},
	chapters = {
		{
			title = "O Salto de Fé",
			hint = "Prove sua fé na altura de Dorn.",
			text = [=[A primeira prova de Dorn é a mais estranha. Ele pede aos jovens que saltem das tábuas de sua altura para o ar vazio, sem promessa de que viverão. A fé, ensina ele, importa mais do que muitos percebem. Nem sempre importa em que se crê, mas sim que se creia em algo.]=],
		},
		{
			title = "Corpo e Força",
			hint = "Passe nas provas de resistência e de força.",
			text = [=[Para o corpo, Dorn envia os jovens ao {link:roguefeather-den}Covil Plumerrante{/link} para estragar as provisões das harpias e enfrentar {link:grenka-bloodscreech}Grenka Bloodscreech{/link} quando ela vier em sua fúria. Para a força, envia-os contra {link:rok-alim-the-pounder}Rok'Alim{/link}, um elemental que permanece nas Agulhas desde a era dos Deuses Antigos.]=],
		},
		{
