Translate("ptBR", "pozzik", {
	title = "Pozzik",
	subtitle = "Mecânico-chefe dos Corredores Goblins",
	found = "Os boxes goblins do Circuito da Ilusão",
	hint = [=[Fale com o mecânico goblin nos boxes goblins do Circuito da Ilusão.]=],
	allegiance = "Cartel Bondebico · Equipe de corrida goblin",
	sections = {
		{
			title = "Resumo",
			text = [=[Pozzik foi outrora um dos engenhoqueiros mais respeitados de Undermine. Deixou para trás o Sindicato dos Engenhoqueiros para trabalhar com carros de corrida, e a primeira coisa que fez foi projetar os modelos de dois motores que a equipe goblin ainda pilota. Agora ele lidera seus mecânicos na {link:the-shimmering-flats}Chapada Cintilante{/link}. Pesa cada parafuso e cada osso, porque nas corridas cada grama conta.]=],
		},
		{
			title = "Importância",
			text = [=[Pozzik é o cérebro da equipe goblin, e está perdendo. Os gnomos estão alcançando-o, e ele fará quase tudo para manter o ritmo: recorrer aos barões e construtores goblins que o patrocinam, e roubar dos rivais se for preciso.]=],
		},
		{
			title = "Feitos",
			text = [=[• Projetou os carros de corrida goblins de dois motores.
• Constrói suas estruturas com os ossos ocos dos abutres da Chapada.
• Buscou um novo regulador de combustível por meio de {link:gazlowe}Gazlowe{/link}, de {link:ratchet}Vila Catraca{/link}, e do {link:baron-revilgaz}Barão Revilgaz{/link}, de {link:booty-bay}Angra do Butim{/link}.
• Mandou roubar os planos de Rizzle Brassbolts, e com eles descobriu o segredo do indúrio.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu sobre os anos de Pozzik em Undermine ou sobre por que ele os deixou.]=],
		},
	},
	chapters = {
		{
			title = "Patrocínio Goblin",
			hint = [=[Descubra o que aconteceu com o regulador de combustível prometido a Pozzik.]=],
			text = [=[{link:gazlowe}Gazlowe{/link} havia prometido um novo regulador de combustível, e ele nunca chegou. A trilha foi de {link:ratchet}Vila Catraca{/link} aos cais de {link:booty-bay}Angra do Butim{/link} e ao {link:baron-revilgaz}Barão Revilgaz{/link}, que admitiu que seus homens não haviam conseguido encontrar as plantas. Os planos estavam na casa de um capataz da {link:venture-company}Empreendimentos S.A.{/link} na {link:stranglethorn-vale}Selva do Espinhaço{/link}, que havia instalado o novo regulador em seus retalhadores. Quando as plantas enfim chegaram a Pozzik, eram apenas desenhos. Ele ficou satisfeito mesmo assim, pois agora podia melhorar o projeto desde a base.]=],
		},
		{
			title = "Mantendo o Ritmo",
			hint = "Ajude Pozzik a descobrir o segredo da velocidade dos gnomos.",
			text = [=[Os carros gnômicos haviam ficado mais rápidos, mas todos os projetos que Pozzik conseguia ver eram iguais aos de antes. Ele concluiu que os gnomos haviam encontrado um material novo. Enquanto Zamek provocava uma distração, os planos de Rizzle Brassbolts foram tirados debaixo de seu nariz. Falavam do indúrio, um minério da escavação anã de {link:uldaman}Uldaman{/link} que resiste a grande calor, e um pedaço dele vinha sendo usado como peso de papel.]=],
		},
	},
	mentions = {
		{ text = "Aliviando a Carga" },
		{ text = "Patrocínio Goblin" },
		{ text = "Patrocínio Goblin, as plantas trazidas para casa" },
		{ text = "O Décimo Oitavo Piloto" },
		{ text = "Mantendo o Ritmo" },
		{ text = "Os Esquemas de Rizzle" },
		{ text = "Minério de Indúrio" },
	},
	bonds = {
		{ id = "razzeric", name = "Razzeric", note = "o piloto da equipe" },
		{ id = "gazlowe", name = "Gazlowe", note = "um patrocinador" },
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "um rival" },
		{ id = "race-master-kronkrider", name = "Mestre de Corrida Kronkrider", note = "comanda a pista" },
	},
})

