	aliases = { "Kravel" },
	sections = {
		{
			title = "Resumo",
			text = [=[Kravel Koalbeard faz questão de conseguir para as pessoas o que elas precisam, e de ficar com sua parte no caminho. Compra os destroços dos carros acidentados e os revende à equipe que pagar. Atende aos pedidos dos gnomos, e guarda um pouquinho de cada um para si. Acredita que sempre há lucro na desgraça alheia, e diz isso abertamente.]=],
